mapper.select:
SELECT compliment_id, match_id, rater_id, ratee_id, comment, created_at
FROM compliment
WHERE compliment_id = #{complimentId}

SELECT COUNT(*)
FROM compliment
WHERE match_id = #{matchId}
AND rater_id = #{raterId}
AND ratee_id = #{rateeId}

SELECT compliment_id, match_id, rater_id, ratee_id, comment, created_at
FROM compliment
WHERE ratee_id = #{memberId}

    AND compliment_id < #{cursor}

ORDER BY compliment_id DESC
LIMIT #{size}
